<script setup lang="ts">import { onBeforeUnmount, onMounted, ref } from 'vue'; import GText from '../../content/GText/GText.vue'; import type { TextContent } from '@/shared/types/components'; withDefaults(defineProps<{ open?: boolean; openLabel?: TextContent }>(), { open: false, openLabel: () => ({ table: 'Common', textKey: '#OPEN' }) }); const emit = defineEmits<{ 'update:open': [value: boolean] }>(); const root = ref<HTMLElement | null>(null); function close(event: Event) { if (!root.value?.contains(event.target as Node)) emit('update:open', false) } function escape(event: KeyboardEvent) { if (event.key === 'Escape') emit('update:open', false) } onMounted(() => { document.addEventListener('pointerdown', close); document.addEventListener('keydown', escape) }); onBeforeUnmount(() => { document.removeEventListener('pointerdown', close); document.removeEventListener('keydown', escape) })</script>
<template><div ref="root" class="ew-dropdown" :data-state="open ? 'open' : 'closed'"><button class="ew-button" type="button" :aria-expanded="open" aria-haspopup="true" @click="emit('update:open', !open)"><slot name="trigger"><GText :content="openLabel" /></slot></button><div v-if="open" class="ew-popover"><slot /></div></div></template>
